mapper.select:
select alt.task_id, alt.task_name, alt.base_dataset_id, abd.base_dataset_name,alt.intelligent_annotation_url,alt.description, alt.label_type,alt.sub_label_type,alt.data_type,alt.tag_ids,abd.count as image_count,alt.create_time, alt.create_by, alt.update_time, alt.update_by,count(case when al.del_flag ='0' then 1 end) as label_count from aircas_label_task alt left join aircas_base_dataset abd on alt.base_dataset_id = abd.base_dataset_id left join aircas_label al on al.task_id = alt.task_id
alt.del_flag = '0'
and alt.task_id = #{query.taskId}
and alt.base_dataset_id = #{query.baseDatasetId}
and alt.task_name like concat('%',#{query.taskName},'%')
and alt.label_type = #{query.labelType}
group by alt.task_id order by max(alt.create_time) desc

select abd.base_dataset_id,abd.base_dataset_name,abd.data_type,abd.label_type,abd.count
from aircas_base_dataset abd
where abd.del_flag = '0'

	and abd.base_dataset_id = #{query.baseDatasetId}

and exists(
select 1
from aircas_label_task alt
where alt.del_flag = '0' and alt.base_dataset_id = abd.base_dataset_id

	and alt.task_id = #{query.taskId}


	and alt.task_name like concat('%',#{query.taskName},'%')


	and alt.label_type = #{query.labelType}


	and alt.sub_label_type = #{query.subLabelType}

)
order by abd.create_time desc

select alt.task_id, alt.task_name, alt.base_dataset_id, abd.base_dataset_name, alt.label_type,alt.sub_label_type,alt.data_type,alt.tag_ids,abd.count as image_count,alt.create_time, alt.create_by, alt.update_time,alt.update_by,count(case when al.del_flag ='0' then 1 end) as label_count, alt.intelligent_annotation_url,alt.description from aircas_label_task alt left join aircas_base_dataset abd on alt.base_dataset_id = abd.base_dataset_id left join aircas_label al on al.task_id = alt.task_id
alt.del_flag = '0'
and alt.base_dataset_id in
#{id}
and alt.task_id = #{query.taskId}
and alt.base_dataset_id = #{query.baseDatasetId}
and alt.task_name like concat('%',#{query.taskName},'%')
and alt.label_type = #{query.labelType}
and alt.sub_label_type = #{query.subLabelType}
group by alt.task_id order by max(alt.create_time) desc
